CREATE TABLE IF NOT EXISTS connector_certification_packs(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,family_key TEXT NOT NULL,display_name TEXT NOT NULL,category TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('UNCONFIGURED','CREDENTIALS_PRESENT','HEALTH_CHECK_PASSED','SANDBOX_CERTIFIED','PRODUCTION_ENABLED','DEGRADED','REVOKED')),provider_mode TEXT NOT NULL,production_enabled INTEGER NOT NULL DEFAULT 0 CHECK(production_enabled IN(0,1)),contract_profile_json TEXT NOT NULL,last_certified_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(organization_id,property_id,family_key));
CREATE TABLE IF NOT EXISTS connector_certification_runs(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,family_key TEXT NOT NULL,scenario TEXT NOT NULL,status TEXT NOT NULL,idempotency_key TEXT NOT NULL,signature_verified INTEGER NOT NULL,receipt_json TEXT NOT NULL,retry_count INTEGER NOT NULL,dead_lettered INTEGER NOT NULL,circuit_open INTEGER NOT NULL,reconciled INTEGER NOT NULL,executed_by TEXT NOT NULL,executed_at TEXT NOT NULL,UNIQUE(organization_id,property_id,family_key,scenario,idempotency_key));
CREATE INDEX IF NOT EXISTS connector_certification_scope_idx ON connector_certification_packs(organization_id,property_id,state,family_key);
CREATE INDEX IF NOT EXISTS connector_certification_run_scope_idx ON connector_certification_runs(organization_id,property_id,family_key,executed_at);
